import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"PFAS 与光刻胶管制","description":"","frontmatter":{"title":"PFAS 与光刻胶管制","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pfas-resist-regulation.md","filePath":"litho/pfas-resist-regulation.md","lastUpdated":1789023840000}'),c={name:"litho/pfas-resist-regulation.md"};function A(P,a,_,u,E,f){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="pfas-与光刻胶管制" tabindex="-1">PFAS 与光刻胶管制 <a class="header-anchor" href="#pfas-与光刻胶管制" aria-label="Permalink to &quot;PFAS 与光刻胶管制&quot;">​</a></h1><div class="epigraph"><p>光酸发生剂与表面活性剂常含氟烷基；PFAS 管制若一刀切，先进胶配方会先于光学碰到法规墙。</p><footer>—— 对照半导体光刻中 PFAS 用途与 2020s 监管讨论的公开产业/SPIE 叙述</footer></div><p><a href="/litho/supply-chain-single-source">上一课</a>谈工具集中。缺口是材料许可。本课钉 PFAS 与光刻胶管制。代工如何在法规与工具约束下选节点路径，留给[下一课](/litho/foundry-roadmap-compare）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>化学放大胶的 PAG、猝灭剂、表面活性剂、底部抗反射，不少属于广义 PFAS 讨论范围。监管（欧盟等）若限制制造与进口，供应链会像工具一样窄。替代配方必须重新做窗口、随机、缺陷、与 OPC 版本——学习曲线时钟重启。</p><p>缺口是<strong>法规进 PDK</strong>，不是再讲酸扩散。把胶当无限可购的化学品，规划会漏项。</p><h3 id="不要把化学点名写成禁令清单" tabindex="-1">不要把化学点名写成禁令清单 <a class="header-anchor" href="#不要把化学点名写成禁令清单" aria-label="Permalink to &quot;不要把化学点名写成禁令清单&quot;">​</a></h3><p>具体物质与豁免随法域与年份变。本课钉机制：先进节点胶高度依赖含氟功能，替代有周期。不把某公司退出当全球停产的完成时。</p><p><span class="marginnote">湿法与管线里的表面活性剂同样受关注，不只是涂在晶圆上的那一微米。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>跟踪：法规范围、豁免、时间表。工程：替代 PAG 的资格矩阵（E0、LER、随机、金属污染）。版本：胶换即模型换。与出口管制并列进风险登记，对象不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>含氟基团提供酸强度、透明度、表面能，是配方自由度。去掉它们不是改浓度，是改一类化学。资格周期以年计，与节点爬坡重叠则直接进良率学习。</p>',13)),(e(),n(h,null,{default:r(()=>[d(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22PFAS%20%E6%B3%95%E8%A7%84%22%5D%20--%3E%20SUP%5B%22%E8%83%B6%20%2F%20%E8%A1%A8%E9%9D%A2%E6%B4%BB%E6%80%A7%E5%89%82%E4%BE%9B%E7%BB%99%22%5D%0A%20%20SUP%20--%3E%20QUAL%5B%22%E9%87%8D%E6%96%B0%E8%B5%84%E6%A0%BC%20%2B%20OPC%22%5D%0A%20%20QUAL%20--%3E%20CLK%5B%22%E5%AD%A6%E4%B9%A0%E6%97%B6%E9%92%9F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供法律意见。不发明未公布的禁令日期。不把所有氟化学当同一监管对象。</p><p>后课默认：材料许可是约束；下一课代工路线在工具、材料、节点名下如何分叉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>先进胶与湿法含 PFAS 讨论对象；管制会重启资格与 OPC。</li><li>替代不是调浓度，是换化学自由度。</li><li>与工具集中并列，进风险登记。</li><li>出处：光刻 PFAS 用途与监管的公开产业/SPIE 讨论。</li></ul>',5))])}const B=i(c,[["render",A]]);export{S as __pageData,B as default};
